# R3 keyword and listed terms linking
import html as _d10_html, urllib.parse as _d10_url
_d10_terms = [line.strip() for line in open('scratch/audits/day-010-terms.txt').read().splitlines() if line.strip()]
_d10_pat = re.compile(r'(?<!\w)(' + '|'.join(re.escape(t) for t in sorted(_d10_terms, key=len, reverse=True)) + r')(?!\w)', re.I)

def _d10_link_terms(value):
    stack, seen, out = [], set(), []
    for token in re.split(r'(<[^>]+>)', value):
        if token.startswith('<'):
            tag = re.match(r'<([/a-zA-Z0-9]+)', token)
            name = tag.group(1).lower() if tag else ''
            if name.startswith('/'):
                if stack and stack[-1] == name[1:]: stack.pop()
            elif not token.endswith('/>'):
                stack.append(name)
            out.append(token)
            continue
        if any(t in stack for t in ('a', 'code', 'kbd', 'samp', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'figcaption')):
            out.append(token)
            continue
        def wrap(m):
            term = m.group(0)
            if term.casefold() in seen: return term
            seen.add(term.casefold())
            return '<a href="http://www.google.com/search?q=' + _d10_url.quote_plus(_d10_html.unescape(term)) + '" rel="noopener" target="_blank">' + term + '</a>'
        out.append(_d10_pat.sub(wrap, token))
    return ''.join(out)

def _d10_link_keywords(html_text):
    def _repl(m):
        inner = m.group(1)
        if '<a ' in inner:
            return m.group(0)
        clean_text = re.sub(r'<[^>]+>', '', inner).strip()
        search_url = 'http://www.google.com/search?q=' + _d10_url.quote_plus(clean_text)
        return '<strong class="keyword"><a href="' + search_url + '" target="_blank" rel="noopener">' + inner + '</a></strong>'
    return re.sub(r'<strong class="keyword">(.*?)</strong>', _repl, html_text)

DATA['part1_html'] = _d10_link_terms(_d10_link_keywords(DATA['part1_html']))

for _t in DATA['topics']:
    _t['technical'] = _d10_link_terms(_d10_link_keywords(_t['technical']))

